-- =============================================================================
-- V4：M2 人物与事件数据模型（六张新表 + 约束 + 索引）
-- 权威依据：
--   03_核心数据模型与时间规范.md §2 天文纪年 / §3 时间区间规则 / §4 时间属性应用位置
--                               §5 核心表建议（person … person_place）/ §7 关系规则
--   CORE_DATA_MODEL_V2.1.1.md  §2 通用约定（命名、主键、时间列风格）
--   V2__core_data_model.sql    既有命名与约束约定（pk_/fk_/ck_/uq_/ix_ 前缀）
--
-- 施工口径：
--   1. 只新增对象，不触碰 V1–V3 已执行的任何 DDL，不改既有九表一列一约束。
--   2. 主键统一 bigint GENERATED BY DEFAULT AS IDENTITY，与既有一致。
--   3. 时间一律天文学纪年整数：公元前 1 年 = 0，公元 1 年 = 1；年份与精度成对出现，
--      “年份为空 ⇔ 精度为 unknown”，避免出现“有精度没年份”或“有年份却标 unknown”。
--   4. 人物/事件允许资料残缺：除名称类字段外，其余业务列均可空。
--   5. 同名不合并：person.canonical_name / event.title 均**不建唯一约束**。
--   6. 删除语义（对应 M2-1 验收第 6 条）：
--        - person / event 被关联表引用时，其关联行 ON DELETE CASCADE
--          （关联行本身不是独立业务对象，随主体消失，不产生孤儿）；
--        - 关联表引用 historical_place 时 ON DELETE RESTRICT
--          （地点是独立业务对象，绝不因为删关联或删主体而连带删地点）。
--   7. created_at / updated_at 给 DEFAULT now() 并由触发器维护 updated_at：
--      人物事件为人工录入表，与导入表（写入方显式提供时间列）场景不同。
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 通用：updated_at 自动维护
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    -- 必须用 clock_timestamp() 而不是 now()：now() 在同一事务内恒为事务开始时间，
    -- 同一事务内连改两行时 updated_at 不会前进（M2-1 测试 G01 实测暴露）。
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION fn_touch_updated_at() IS '行更新时刷新 updated_at，避免写入方遗漏。仅挂在本版新增的人工录入表上。';

-- -----------------------------------------------------------------------------
-- §5 person（历史人物主表）
-- -----------------------------------------------------------------------------
CREATE TABLE person (
    person_id            bigint      GENERATED BY DEFAULT AS IDENTITY,
    canonical_name       text        NOT NULL,
    canonical_name_lang  text,
    description          text,
    birth_year_astro     integer,
    birth_precision      text        NOT NULL DEFAULT 'unknown',
    birth_original_text  text,
    death_year_astro     integer,
    death_precision      text        NOT NULL DEFAULT 'unknown',
    death_original_text  text,
    notes                text,
    record_status        text        NOT NULL DEFAULT 'staging',
    created_by           text        NOT NULL DEFAULT 'manual',
    locked               boolean     NOT NULL DEFAULT false,
    manual_edited_fields text[]      NOT NULL DEFAULT '{}',
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT pk_person PRIMARY KEY (person_id),

    CONSTRAINT ck_person_canonical_name_not_blank
        CHECK (btrim(canonical_name) <> ''),
    -- BCP-47 形态（与 historical_place_name.name_lang 同口径，'und' 除外）
    CONSTRAINT ck_person_name_lang
        CHECK (canonical_name_lang IS NULL
            OR canonical_name_lang ~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$'
            OR canonical_name_lang = 'und'),

    CONSTRAINT ck_person_birth_precision
        CHECK (birth_precision IN ('exact', 'approximate', 'range', 'unknown')),
    CONSTRAINT ck_person_death_precision
        CHECK (death_precision IN ('exact', 'approximate', 'range', 'unknown')),
    -- 年份与精度必须成对：有年 ⇒ 精度不是 unknown；无年 ⇒ 精度就是 unknown
    CONSTRAINT ck_person_birth_time_pair
        CHECK ((birth_year_astro IS NULL) = (birth_precision = 'unknown')),
    CONSTRAINT ck_person_death_time_pair
        CHECK ((death_year_astro IS NULL) = (death_precision = 'unknown')),
    -- 生卒顺序（都已知时才校验；天文纪年整数可直接比较，跨公元前后亦成立）
    CONSTRAINT ck_person_life_order
        CHECK (birth_year_astro IS NULL
            OR death_year_astro IS NULL
            OR birth_year_astro <= death_year_astro),

    CONSTRAINT ck_person_record_status
        CHECK (record_status IN ('staging', 'published', 'rejected')),
    CONSTRAINT ck_person_created_by
        CHECK (created_by IN ('import', 'manual'))
);

COMMENT ON TABLE person IS '历史人物主表。同名人物不自动合并（canonical_name 无唯一约束），资料残缺允许保存。';
COMMENT ON COLUMN person.birth_year_astro IS '天文纪年整数：公元前 1 年 = 0。界面按 1-n 换算显示，不显示公元 0 年。';
COMMENT ON COLUMN person.birth_precision IS 'exact / approximate / range / unknown；为 unknown 时 birth_year_astro 必须为空，反之亦然。';
COMMENT ON COLUMN person.birth_original_text IS '原始文献表述（如「约公元前 551 年」），不改写不推断。';
COMMENT ON COLUMN person.record_status IS 'staging / published / rejected；M2-1 只建结构，发布流程在 M2-2。';

CREATE INDEX ix_p_name        ON person (canonical_name);
CREATE INDEX ix_p_life_years  ON person (birth_year_astro, death_year_astro);

CREATE TRIGGER trg_person_updated_at
    BEFORE UPDATE ON person
    FOR EACH ROW EXECUTE FUNCTION fn_touch_updated_at();

-- -----------------------------------------------------------------------------
-- §5 person_name（人物名称、别名、异体名）
-- -----------------------------------------------------------------------------
CREATE TABLE person_name (
    person_name_id         bigint      GENERATED BY DEFAULT AS IDENTITY,
    person_id              bigint      NOT NULL,
    name_text              text        NOT NULL,
    name_lang              text,
    name_type              text        NOT NULL,
    transliteration_scheme text,
    notes                  text,
    record_status          text        NOT NULL DEFAULT 'staging',
    created_by             text        NOT NULL DEFAULT 'manual',
    locked                 boolean     NOT NULL DEFAULT false,
    manual_edited_fields   text[]      NOT NULL DEFAULT '{}',
    created_at             timestamptz NOT NULL DEFAULT now(),
    updated_at             timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT pk_person_name PRIMARY KEY (person_name_id),
    CONSTRAINT fk_person_name_person
        FOREIGN KEY (person_id) REFERENCES person (person_id) ON DELETE CASCADE,

    CONSTRAINT ck_person_name_text_not_blank
        CHECK (btrim(name_text) <> ''),
    CONSTRAINT ck_person_name_type
        CHECK (name_type IN ('primary', 'alternate', 'transliteration',
                             'historical', 'courtesy', 'art', 'posthumous', 'pseudonym')),
    CONSTRAINT ck_person_name_lang
        CHECK (name_lang IS NULL
            OR name_lang ~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$'
            OR name_lang = 'und'),
    CONSTRAINT ck_person_name_translit
        CHECK (transliteration_scheme IS NULL OR name_type = 'transliteration'),
    CONSTRAINT ck_person_name_record_status
        CHECK (record_status IN ('staging', 'published', 'rejected')),
    CONSTRAINT ck_person_name_created_by
        CHECK (created_by IN ('import', 'manual'))
);

COMMENT ON TABLE person_name IS '人物名称行。name_type 覆盖正名/别名/转写/旧称/字/号/谥号/化名。';
COMMENT ON COLUMN person_name.name_type IS 'primary=正名；alternate=别名；transliteration=转写；historical=旧称；courtesy=字；art=号；posthumous=谥号；pseudonym=化名。';

-- 同一人物下，同一类型 + 同一文本 + 同一语言不得重复。
-- name_lang 可空，直接 UNIQUE 会因 NULL 互不相等而失效，故用 coalesce 表达式索引。
CREATE UNIQUE INDEX uq_pn_name
    ON person_name (person_id, name_type, name_text, coalesce(name_lang, ''));
CREATE INDEX ix_pn_person ON person_name (person_id);
CREATE INDEX ix_pn_name   ON person_name (name_text);

CREATE TRIGGER trg_person_name_updated_at
    BEFORE UPDATE ON person_name
    FOR EACH ROW EXECUTE FUNCTION fn_touch_updated_at();

-- -----------------------------------------------------------------------------
-- §5 event（历史事件主表）
-- -----------------------------------------------------------------------------
CREATE TABLE event (
    event_id           bigint      GENERATED BY DEFAULT AS IDENTITY,
    title              text        NOT NULL,
    summary            text,
    description        text,
    start_year_astro   integer,
    end_year_astro     integer,
    time_precision     text        NOT NULL DEFAULT 'unknown',
    time_original_text text,
    time_note          text,
    event_type         text        NOT NULL DEFAULT 'unknown',
    notes              text,
    record_status      text        NOT NULL DEFAULT 'staging',
    created_by         text        NOT NULL DEFAULT 'manual',
    locked             boolean     NOT NULL DEFAULT false,
    manual_edited_fields text[]    NOT NULL DEFAULT '{}',
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT pk_event PRIMARY KEY (event_id),

    CONSTRAINT ck_event_title_not_blank
        CHECK (btrim(title) <> ''),
    CONSTRAINT ck_event_type_not_blank
        CHECK (btrim(event_type) <> ''),

    CONSTRAINT ck_event_time_precision
        CHECK (time_precision IN ('exact', 'approximate', 'range', 'unknown')),
    -- 精度 unknown ⇒ 起止年都为空
    CONSTRAINT ck_event_time_unknown_has_no_year
        CHECK (time_precision <> 'unknown'
            OR (start_year_astro IS NULL AND end_year_astro IS NULL)),
    -- 精度已知 ⇒ 至少有开始年（允许「始于某年、止年不详」的开放区间）
    CONSTRAINT ck_event_time_known_has_start
        CHECK (time_precision = 'unknown' OR start_year_astro IS NOT NULL),
    -- 区间端点包含式，起不得晚于止
    CONSTRAINT ck_event_time_order
        CHECK (start_year_astro IS NULL
            OR end_year_astro IS NULL
            OR start_year_astro <= end_year_astro),

    CONSTRAINT ck_event_record_status
        CHECK (record_status IN ('staging', 'published', 'rejected')),
    CONSTRAINT ck_event_created_by
        CHECK (created_by IN ('import', 'manual'))
);

COMMENT ON TABLE event IS '历史事件主表。允许只知开始年（end_year_astro 为空 = 开放区间）。同名事件不合并。';
COMMENT ON COLUMN event.start_year_astro IS '天文纪年整数。时间区间按「端点包含式」解释。';
COMMENT ON COLUMN event.time_precision IS 'unknown 时起止年必须都为空；非 unknown 时 start_year_astro 必填。';
COMMENT ON COLUMN event.event_type IS '事件类型，本版不做枚举（设计文档未给定值域），只要求非空；取值规范待 M2-2 与产品确认。';

CREATE INDEX ix_e_time  ON event (start_year_astro, end_year_astro);
CREATE INDEX ix_e_title ON event (title);

CREATE TRIGGER trg_event_updated_at
    BEFORE UPDATE ON event
    FOR EACH ROW EXECUTE FUNCTION fn_touch_updated_at();

-- -----------------------------------------------------------------------------
-- §5 event_place（事件 × 地点）
-- -----------------------------------------------------------------------------
CREATE TABLE event_place (
    event_place_id        bigint      GENERATED BY DEFAULT AS IDENTITY,
    event_id              bigint      NOT NULL,
    place_id              bigint      NOT NULL,
    location_role         text        NOT NULL DEFAULT 'unknown',
    valid_from_year_astro integer,
    valid_to_year_astro   integer,
    note                  text,
    created_at            timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT pk_event_place PRIMARY KEY (event_place_id),
    -- 主体被删 → 关联随之消失（关联行不是独立业务对象）
    CONSTRAINT fk_event_place_event
        FOREIGN KEY (event_id) REFERENCES event (event_id) ON DELETE CASCADE,
    -- 地点绝不被连带删除
    CONSTRAINT fk_event_place_place
        FOREIGN KEY (place_id) REFERENCES historical_place (place_id) ON DELETE RESTRICT,

    CONSTRAINT ck_event_place_role_not_blank
        CHECK (btrim(location_role) <> ''),
    CONSTRAINT ck_event_place_valid_order
        CHECK (valid_from_year_astro IS NULL
            OR valid_to_year_astro IS NULL
            OR valid_from_year_astro <= valid_to_year_astro)
);

COMMENT ON TABLE event_place IS '事件与地点的多对多关联。一个事件可关联多个地点。可选记录关系有效期。';
COMMENT ON COLUMN event_place.location_role IS '该地点在事件中的角色，如 origin / battlefield / destination / unknown。本版不做枚举。';

-- 同一事件、同一地点、同一角色只允许一行（不同角色可并存）
CREATE UNIQUE INDEX uq_event_place
    ON event_place (event_id, place_id, location_role);
CREATE INDEX ix_epl_place ON event_place (place_id);

-- -----------------------------------------------------------------------------
-- §5 event_person（事件 × 人物）
-- -----------------------------------------------------------------------------
CREATE TABLE event_person (
    event_person_id       bigint      GENERATED BY DEFAULT AS IDENTITY,
    event_id              bigint      NOT NULL,
    person_id             bigint      NOT NULL,
    role                  text        NOT NULL DEFAULT 'unknown',
    valid_from_year_astro integer,
    valid_to_year_astro   integer,
    note                  text,
    created_at            timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT pk_event_person PRIMARY KEY (event_person_id),
    CONSTRAINT fk_event_person_event
        FOREIGN KEY (event_id) REFERENCES event (event_id) ON DELETE CASCADE,
    CONSTRAINT fk_event_person_person
        FOREIGN KEY (person_id) REFERENCES person (person_id) ON DELETE CASCADE,

    CONSTRAINT ck_event_person_role_not_blank
        CHECK (btrim(role) <> ''),
    CONSTRAINT ck_event_person_valid_order
        CHECK (valid_from_year_astro IS NULL
            OR valid_to_year_astro IS NULL
            OR valid_from_year_astro <= valid_to_year_astro)
);

COMMENT ON TABLE event_person IS '事件与历史人物的多对多关联。一个事件可关联多个人物。';
COMMENT ON COLUMN event_person.role IS '人物在事件中的角色，如 participant / commander / victim / unknown。本版不做枚举。';

CREATE UNIQUE INDEX uq_event_person
    ON event_person (event_id, person_id, role);
CREATE INDEX ix_ep_person ON event_person (person_id);

-- -----------------------------------------------------------------------------
-- §5 person_place（人物 × 活动地点）
-- -----------------------------------------------------------------------------
CREATE TABLE person_place (
    person_place_id     bigint      GENERATED BY DEFAULT AS IDENTITY,
    person_id           bigint      NOT NULL,
    place_id            bigint      NOT NULL,
    relation_type       text        NOT NULL,
    start_year_astro    integer,
    end_year_astro      integer,
    time_precision      text        NOT NULL DEFAULT 'unknown',
    sequence_order      integer,
    note                text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT pk_person_place PRIMARY KEY (person_place_id),
    CONSTRAINT fk_person_place_person
        FOREIGN KEY (person_id) REFERENCES person (person_id) ON DELETE CASCADE,
    CONSTRAINT fk_person_place_place
        FOREIGN KEY (place_id) REFERENCES historical_place (place_id) ON DELETE RESTRICT,

    CONSTRAINT ck_person_place_relation_not_blank
        CHECK (btrim(relation_type) <> ''),
    CONSTRAINT ck_person_place_time_precision
        CHECK (time_precision IN ('exact', 'approximate', 'range', 'unknown')),
    CONSTRAINT ck_person_place_time_unknown_has_no_year
        CHECK (time_precision <> 'unknown'
            OR (start_year_astro IS NULL AND end_year_astro IS NULL)),
    CONSTRAINT ck_person_place_time_known_has_start
        CHECK (time_precision = 'unknown' OR start_year_astro IS NOT NULL),
    CONSTRAINT ck_person_place_time_order
        CHECK (start_year_astro IS NULL
            OR end_year_astro IS NULL
            OR start_year_astro <= end_year_astro),
    CONSTRAINT ck_person_place_sequence_positive
        CHECK (sequence_order IS NULL OR sequence_order >= 1)
);

COMMENT ON TABLE person_place IS '人物与活动地点的多对多关联。保留关系类型与有效时间范围；同一人可多时段到访同一地点。';
COMMENT ON COLUMN person_place.relation_type IS '关系类型，如 birthplace / residence / activity / death / unknown。本版不做枚举。';
COMMENT ON COLUMN person_place.sequence_order IS '已知活动顺序时用于排序；仅用于绘制示意连线，不代表真实行进轨迹。';

CREATE UNIQUE INDEX uq_person_place
    ON person_place (person_id, place_id, relation_type,
                     coalesce(start_year_astro, -2147483648));
CREATE INDEX ix_pp_place ON person_place (place_id);
CREATE INDEX ix_pp_years ON person_place (start_year_astro, end_year_astro);

CREATE TRIGGER trg_person_place_updated_at
    BEFORE UPDATE ON person_place
    FOR EACH ROW EXECUTE FUNCTION fn_touch_updated_at();
